# Build a Gray-code walk from current 10010 (18), visiting every other 5-bit code once.
start=18
seen={start}; walk=[]; cur=start
while len(seen)<32:
    for bit in range(5):
        nxt=cur^(1<<bit)
        if nxt not in seen:
            walk.append((nxt,bit))
            seen.add(nxt);cur=nxt;break
[(format(n,'05b'),b) for n,b in walk], len(walk)
